import{_ as i,c as t,o as s,a9 as n,ap as a}from"./chunks/framework.C3PHgg-M.js";const m=JSON.parse('{"title":"Subscription","description":"How to add a subscription to a PURISTA typescript framework service","frontmatter":{"title":"Subscription","description":"How to add a subscription to a PURISTA typescript framework service","order":203000},"headers":[],"relativePath":"handbook/2_building_business-logic/subscription/index.md","filePath":"handbook/2_building_business-logic/subscription/index.md","lastUpdated":1778094759000}'),o={name:"handbook/2_building_business-logic/subscription/index.md"};function r(l,e,c,u,d,p){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="subscription" tabindex="-1">Subscription <a class="header-anchor" href="#subscription" aria-label="Permalink to “Subscription”">​</a></h1><p><img src="'+a+'" alt="Add subscription with cli"></p><p>A subscription is a function which will be triggered by messages and events, when the given criteria are matching. The producer of the message does not have knowledge about the subscription.</p><p>Subscriptions do not need to return a value. If a subscription is returning a value, it will be emitted as custom message to the event bridge. The subscription does not have any knowledge if the custom message has a consumer.</p><p>Subscriptions can access service resources (for example database clients/connections) via <code>context.resources</code>. Resources are provided when creating the service instance with <code>serviceBuilder.getInstance(eventBridge, { resources: ... })</code>. Subscriptions can also consume stream endpoints via <code>context.stream</code> when declared with <code>.canConsumeStream(...)</code>. Typical use cases:</p><ul><li>update projections/read models after command success events</li><li>send emails/notifications after business events</li><li>trigger asynchronous integrations with external systems</li><li>run cross-cutting reactions like auditing and metrics enrichment</li></ul><p>In PURISTA, subscriptions are declared with the subscription builder:</p><ul><li>define input/parameter/output schemas</li><li>configure matching filters (event name, sender/receiver, message type, tenant/principal)</li><li>optionally define invokes and emitted events</li><li>provide the subscription function implementation</li></ul><p>Continue with:</p><ul><li><a href="./the-subscription-builder.html">The Subscription Builder</a></li><li><a href="./unit-test-a-subscription.html">Unit test a subscription</a></li><li><a href="./../../6_integrations/enterprise_interoperability/event-to-queue.html">Enterprise event-to-queue handoff</a></li></ul><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><ul><li>You need asynchronous side effects.</li><li>Multiple consumers should react to domain events.</li><li>Work should continue even if the original caller is gone.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to “Common pitfalls”">​</a></h2><ul><li>using subscriptions for synchronous request/response logic</li><li>overly broad filters causing unexpected message matches</li><li>assuming broker delivery guarantees that are not configured</li><li>doing long-running work directly instead of handing off to a queue</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to “Checklist”">​</a></h2><ul><li>filter scope is explicit (event/message/sender/tenant/principal)</li><li>durable/shared/ack hints are aligned with the broker setup</li><li>emitted events (if any) have explicit schemas</li><li>unit tests cover matching and non-matching scenarios</li></ul>',16)])])}const b=i(o,[["render",r]]);export{m as __pageData,b as default};
